import{_ as i,a0 as s,w as d,s as p,I as l,x as t,a1 as r,A as e}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const k=JSON.parse('{"title":"為什麼主線內核不能運行在我的手機上？ | LCTT x X-CMD","titleTemplate":false,"description":"為什麼主線內核不能運行在我的手機上？ | LCTT (201601) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"為什麼主線內核不能運行在我的手機上？ | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"為什麼主線內核不能運行在我的手機上？ | LCTT (201601) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201601/20151125 Running a mainline kernel on a cellphone","title":"為什麼主線內核不能運行在我的手機上？","tag":"201601","desc":""},"relativePath":"201601/20151125 Running a mainline kernel on a cellphone.md","filePath":"[post].md"}'),u={name:"201601/20151125 Running a mainline kernel on a cellphone.md"};function m(f,n,g,T,a,b){const o=s("Link");return d(),p("div",null,[n[25]||(n[25]=l("h1",{id:"為什麼主線內核不能運行在我的手機上",tabindex:"-1"},[t("為什麼主線內核不能運行在我的手機上？ "),l("a",{class:"header-anchor",href:"#為什麼主線內核不能運行在我的手機上","aria-label":"Permalink to “為什麼主線內核不能運行在我的手機上？”"},"​")],-1)),n[26]||(n[26]=l("p",null,"對於自由軟件來説，其最大的自由之一就是能夠用一個更新或修改的版本來替換原始版本的程序。儘管如此，數千萬使用那些手機裏面裝着所謂 Linux 的用户卻很少能夠在他們的手機上運行主線內核（mainline kernel），即使他們擁有替換內核代碼的專業技能。可悲的是，我們必須承認目前仍然沒有可以運行主線內核的主流手機。在由 Rob Herring 主持的2015屆內核峯會（Kernel Summit）上，與會人員共同探討了這個問題，並進一步談論了他們應該怎麼做才能解決這個問題。",-1)),l("p",null,[n[1]||(n[1]=t("當主持人提問的時候，在座的大多數開發人員都表示他們更樂意在他們的手機上面運行主線內核，然而也有少數人持相反的看法。在 Project Ara 的支持下，Rob 在這個問題上已經研究了近一年半的時間（參見：",-1)),r(o,{href:"https://lwn.net/Articles/648400/"},{default:e(()=>[...n[0]||(n[0]=[t("https://lwn.net/Articles/648400/",-1)])]),_:1}),n[2]||(n[2]=t(" ）。但是最新的研究成果並不理想。",-1))]),n[27]||(n[27]=l("p",null,"Rob 表示，通常手機上運行了太多的過期(out-of-tree)代碼；主線內核只是缺少能使手機正常運行所必須的驅動。每台常規的手機都在運行着100萬行到300萬行的過期(out-of-tree)代碼。幾乎所有的這些手機的內核版本都不超過3.10，有一些甚至更加古老。造成這種情況的原因有很多，但是有一點是很清楚的，在手機的世界裏，一切都變化的太快以至於無法跟上內核社區的步伐。如果真是那樣，他問到，我們還擔心什麼呢？",-1)),l("p",null,[n[4]||(n[4]=t("Tim Bird 指出，第一台 Android 手機 Nexus 1 從來沒有運行過任何一個主線內核，並且以後也不會。它打破了開源的承諾，也使得用户不可能做到將一個新的內核放到手機中。從這一點上來説，沒有任何一款手機支持這種能力。Peter Zijlstra 想知道從一台手機到另一台手機到底複製了多少能夠工作的過期代碼；Rob表示，迄今為止，他已經見到了三個獨立開發的熱插拔 ",-1)),r(o,{href:"http://androidmodguide.blogspot.com/p/blog-page.html"},{default:e(()=>[...n[3]||(n[3]=[t("Governors",-1)])]),_:1}),n[5]||(n[5]=t("。",-1))]),n[28]||(n[28]=l("p",null,"Dirk Hohndel 提出了很少有人注意到的建議。他説，對於世界上的數以億計的手機，大約只有他們27個人關心他們的手機是否運行着主線內核。剩下的用户僅僅只是想讓他們的手機正常工作。或許那些關注手機是否在運行主線內核的開發者正在努力去解決這個令人不解的問題。",-1)),n[29]||(n[29]=l("p",null,"Chris Mason 説，那些手機廠商當前正面臨着相同類型的問題，而這些問題也是那些 Linux 發行版過去所面臨過的問題。他們疲於應付大量的無效且重複和能被複用的工作。一旦這些發行版決定將他們的工作配合主線內核而不是使用自己維護的內核，那麼問題將會變得好解決的多。解決問題的關鍵就是去幫助手機制造商們認識到他們可以通過同樣的方式獲得便利，形成這種認識的關鍵並不是通過來自用户的壓力。這樣一來，問題就可以解決了。",-1)),l("p",null,[n[7]||(n[7]=t("Grant Likely 提出了對於安全問題的擔憂，這種擔憂來自於那些不能升級他們的手機系統的 android 設備。他説，我們需要的是一個真正專為手機設立的發行版。但是，只要手機廠商仍然掌控着手機中的應用軟件，那麼手機的同步更新將無法實現。我們接下來將面臨一個很大的安全難題。Peter 補充説，隨着 ",-1)),r(o,{href:"https://lwn.net/Articles/652728/"},{default:e(()=>[...n[6]||(n[6]=[t("Stagefright 漏洞",-1)])]),_:1}),n[8]||(n[8]=t("的出現，難題已經出現在我們面前了。",-1))]),n[30]||(n[30]=l("p",null,"Ted Ts'o 説，運行主線內核並不是他的主要關注點。他很樂於見到這個假期中所售賣的手機能夠運行3.18或者4.1的內核，而不是繼續停留在3.10。他認為這是一個更可能被解決的問題。Steve Rostedt 認為，按照 Ted Ts'o 所説的那樣去做並不能解決手機的安全問題，但是，Ted 認為使用一個更新一些的內核至少可以讓漏洞修復變得更加容易。Grant 對此回應説，接下來的一年裏，這一切都將再次發生。過渡到更新的內核也是一個漸進式的對系統的完善。Kees Cook 補充説，我們無法從修復舊版本的內核漏洞的過程中得到太多的益處，真正的問題是我們沒有對 bug 的應對措施（他會在今天的另外一個對話中講到這個話題）。",-1)),n[31]||(n[31]=l("p",null,"Rob 説，任何一種解決方案都需要得到當前市場上的手機供應商的支持。否則，由於廠商對安裝到他們生產的手機上的操作系統的封鎖，運行主線內核的策略將會陷入麻煩。Paolo Bonzini 提問説是否可以因為那些沒有修復的安全漏洞而控告手機廠商，尤其當手機仍然處於保修期內。Grant 認為對於手機的可更新能力（upgradeability）的保證必須來源於市場需求，否則是無法實現的。而促使它實現的原因可能會是一個嚴重的安全問題，然後用户開始對手機的可更新能力提出要求。同時，內核開發人員必須不斷朝着這個方向努力。Rob 表示，除了到目前為止指出的所有優點之外，運行主線內核也能幫助開發者對安卓設備上的新特性進行測試和驗證。",-1)),l("p",null,[n[10]||(n[10]=t("Josh Triplett 提問説，如果手機廠商提出對主線內核提供支持的想法，那麼內核社區又將採取什麼措施呢？那樣將會針對手機各方面的特性要求對內核進行大量的測試和驗證；",-1)),r(o,{href:"https://source.android.com/compatibility/cts/index.html"},{default:e(()=>[...n[9]||(n[9]=[t("Android 的兼容性測試套件",-1)])]),_:1}),n[11]||(n[11]=t("中出現的失敗將不得不被再次迴歸到內核。Rob 提議這個問題可以在明年討論，即先將最基本的功能做好。但是，Josh 強調説，如果這個需求出現了，我們就應該能夠給出一個好的答案。",-1))]),n[32]||(n[32]=l("p",null,"Tim 認為，當前，我們和廠商之間存在很大的脱節。廠商根本不會主動報告或者貢獻任何反饋給社區。他們之間完全脱節了，這樣的話永遠不會有進步。Josh 表示，當廠商們開始報告他們正在使用的舊內核的相關 bug 時，雙方之間的接受度將變得更加友好。Arnd Bergmann 認為，我們需要的是得到一個大芯片廠商對使用主線內核的認可，並且將該廠商的硬件提升到能夠支持主線內核的運行的這樣一個水平，而這樣將會在其他方面增加負擔。但是，他補充説，實現這個目標要求存在一個跟隨硬件一起分發的自由 GPU 驅動程序——然而這種程序當前並不存在。",-1)),n[33]||(n[33]=l("p",null,"Rob 給存在問題的領域列了一個清單，但是現在已經沒有太多的時間去討論其中的細節了。WiFi 驅動仍然是一個問題，尤其是當這個新特性被添加到 Android 設備上的時候。Johannes Berg 對新特性仍然存在問題表示贊同；Android 的開發人員甚至在這些新特性被應用到 Android 設備上之前都不會去談論它們是否存在問題。然而，對這些特性中的大多數的技術支持最終都會落實在主線內核中。",-1)),n[34]||(n[34]=l("p",null,"隨着會議逐漸接近尾聲，Ben Herrenschmidt 再次重申：實現在 Android 手機上運行主線內核的關鍵還是在於讓廠商認識到使用主線內核是它們獲得最大利潤的最好選擇。從長遠看，使用主線內核能節省大量的工作。Mark Brown 認為，以前，當搭載在 Android 設備上的內核版本以更穩定的方式向前推進的時候，上游工作的好處對運營商來説更加明顯。以現在的情況來看，手機上的內核版本似乎停留在了3.10，那種壓力是不一樣的。",-1)),n[35]||(n[35]=l("p",null,"這次談話以開發者決定進一步改善當前的狀況而結束，但是卻並沒有對如何改善提出一個明確的計劃。",-1)),n[36]||(n[36]=l("hr",null,null,-1)),l("p",null,[n[13]||(n[13]=t("via: ",-1)),r(o,{href:"https://lwn.net/Articles/662147/"},{default:e(()=>[...n[12]||(n[12]=[t("https://lwn.net/Articles/662147/",-1)])]),_:1})]),l("p",null,[n[17]||(n[17]=t("作者：",-1)),r(o,{href:"https://lwn.net/Articles/KernelSummit2015/"},{default:e(()=>[...n[14]||(n[14]=[t("Jonathan Corbet",-1)])]),_:1}),n[18]||(n[18]=t(" 譯者：",-1)),r(o,{href:"https://github.com/kylepeng93"},{default:e(()=>[...n[15]||(n[15]=[t("kylepeng93",-1)])]),_:1}),n[19]||(n[19]=t(" 校對：",-1)),r(o,{href:"https://github.com/wxy"},{default:e(()=>[...n[16]||(n[16]=[t("wxy",-1)])]),_:1})]),l("p",null,[n[22]||(n[22]=t("本文由 ",-1)),r(o,{href:"https://github.com/LCTT/TranslateProject"},{default:e(()=>[...n[20]||(n[20]=[t("LCTT",-1)])]),_:1}),n[23]||(n[23]=t(" 原創翻譯，",-1)),r(o,{href:"http://linux.cn/"},{default:e(()=>[...n[21]||(n[21]=[t("Linux中國",-1)])]),_:1}),n[24]||(n[24]=t(" 榮譽推出",-1))])])}const A=i(u,[["render",m]]);export{k as __pageData,A as default};
